const canSwitchTabs = await this.entityViewService.checkUnsavedChanges(
    uiState.isFormOpen,
    uiState.selectedEntity?.Id,
    null,
    this.utils
);

if (!canSwitchTabs) {
    this.utils.setSelectedBelliniTabBarTab(uiState.currentTab.previousId);
    return;
}

uiState.currentTab.previousId = selectedTab;
uiState.isFormOpen = false;
this.baseGridControllerService.resetState(uiState);

const selectedTabName = tabItemsMap.get(selectedTab);
uiState.currentTab.name = selectedTabName;

this.filterOperationsService.onReset(uiState, loaders, false);

uiState.currentFilter.quickSearchPlaceholder = this.filterService.quickSearchConfig.getSearchPlaceholder(
    selectedTabName,
    tabConfig[selectedTabName].quickSearchDefaultConfig,
    this.userPreferenceService
);

loaders.loadActiveTab({
    entityType: selectedTabName,
    page: 1
});

const canSwitch = await this.entityViewService.checkUnsavedChanges(
    uiState.isFormOpen,
    uiState.selectedEntity?.Id,
    null,
    this.utils
);

if (!canSwitch) {
    tabStore[uiState.currentTab.name].currentPage = tabStore[uiState.currentTab.name].previousPage;
    this.$rootScope.$apply();
} else {
    uiState.isFormOpen = false;
    tabStore[uiState.currentTab.name].previousPage = currentPage;
    loaders.loadActiveTab({ page: currentPage });
}
